#include "stdlib/stats/base/dists/chisquare/median.h"
#include "stdlib/stats/base/dists/chisquare/quantile.h"

/**
* Returns the median of a chi-squared distribution.
*
* @param k    degrees of freedom
* @return     median
*
* @example
* double v = stdlib_base_dists_chisquare_median( 9.0 );
* // returns ~8.343
*/
double stdlib_base_dists_chisquare_median( const double k ) {
	return stdlib_base_dists_chisquare_quantile( 0.5, k );
}
